/*
    Bảng log thao tác Booking - dùng chung nhiều form
    -----------------------------------------------------------------------
    FormCode     : mã form/module  (vd: frmDownloadBooking, frmBookingEdit)
    FormName     : tên hiển thị form (vd: Tải lịch hẹn từ HIS)
    ActionType   : DOWNLOAD | UPDATE | INSERT | DELETE | EXPORT | VIEW
    TotalRows    : tổng số dòng liên quan thao tác
    AddCount     : số dòng thêm mới
    UpdateCount  : số dòng cập nhật
    DeleteCount  : số dòng xóa
    FilterInfo   : thông tin bộ lọc/điều kiện (tuNgay, denNgay...)
    RefDataID    : khóa tham chiếu (BookingID, khamBenh_Id...)
    ExtraData    : JSON/text mở rộng cho từng form
    -----------------------------------------------------------------------
    Copy toàn bộ file này vào SQL Server Management Studio và chạy 1 lần.
*/

If Not Exists (Select 1 From sys.tables Where name = 'SYS_BookingLog')
Begin
    Create Table SYS_BookingLog
    (
        BookingLogID    BigInt Identity(1,1) Not Null,
        FormCode        NVarChar(100) Not Null,
        FormName        NVarChar(250) Null,
        ActionType      NVarChar(50) Not Null,
        ActionTitle     NVarChar(500) Null,
        Description     NVarChar(2000) Null,
        TotalRows       Int Null,
        AddCount        Int Null,
        UpdateCount     Int Null,
        DeleteCount     Int Null,
        FilterInfo      NVarChar(1000) Null,
        RefDataID       BigInt Null,
        ExtraData       NVarChar(Max) Null,
        UserID          BigInt Null,
        Username        NVarChar(100) Null,
        IPAddress       NVarChar(50) Null,
        UserAgent       NVarChar(500) Null,
        Url             NVarChar(500) Null,
        SessionID       NVarChar(100) Null,
        IsSuccess       Bit Not Null Constraint DF_SYS_BookingLog_IsSuccess Default(1),
        ErrorMessage    NVarChar(2000) Null,
        CreatedDate     DateTime Not Null Constraint DF_SYS_BookingLog_CreatedDate Default(GetDate()),
        CreatedUser     NVarChar(100) Null,
        UpdatedDate     DateTime Null,
        UpdatedUser     NVarChar(100) Null,
        Constraint PK_SYS_BookingLog Primary Key Clustered (BookingLogID)
    );

    Create NonClustered Index IX_SYS_BookingLog_CreatedDate
        On SYS_BookingLog (CreatedDate Desc);

    Create NonClustered Index IX_SYS_BookingLog_FormCode_ActionType
        On SYS_BookingLog (FormCode, ActionType, CreatedDate Desc);

    Create NonClustered Index IX_SYS_BookingLog_Username
        On SYS_BookingLog (Username, CreatedDate Desc);
End
Go

/* Thêm cột UpdatedDate, UpdatedUser nếu bảng đã tạo trước đó */
If Not Exists (
    Select 1
    From sys.columns
    Where object_id = Object_Id('SYS_BookingLog')
        And name = 'UpdatedDate'
)
Begin
    Alter Table SYS_BookingLog Add UpdatedDate DateTime Null;
End
Go

If Not Exists (
    Select 1
    From sys.columns
    Where object_id = Object_Id('SYS_BookingLog')
        And name = 'UpdatedUser'
)
Begin
    Alter Table SYS_BookingLog Add UpdatedUser NVarChar(100) Null;
End
Go

If Object_Id('SYS_BookingLog_Add', 'P') Is Not Null
    Drop Procedure SYS_BookingLog_Add;
Go

Create Procedure SYS_BookingLog_Add
    @FormCode        NVarChar(100),
    @FormName        NVarChar(250) = Null,
    @ActionType      NVarChar(50),
    @ActionTitle     NVarChar(500) = Null,
    @Description     NVarChar(2000) = Null,
    @TotalRows       Int = Null,
    @AddCount        Int = Null,
    @UpdateCount     Int = Null,
    @DeleteCount     Int = Null,
    @FilterInfo      NVarChar(1000) = Null,
    @RefDataID       BigInt = Null,
    @ExtraData       NVarChar(Max) = Null,
    @UserID          BigInt = Null,
    @Username        NVarChar(100) = Null,
    @IPAddress       NVarChar(50) = Null,
    @UserAgent       NVarChar(500) = Null,
    @Url             NVarChar(500) = Null,
    @SessionID       NVarChar(100) = Null,
    @IsSuccess       Bit = 1,
    @ErrorMessage    NVarChar(2000) = Null,
    @CreatedUser     NVarChar(100) = Null
As
Begin
    Set Nocount On;

    Insert Into SYS_BookingLog
    (
        FormCode,
        FormName,
        ActionType,
        ActionTitle,
        Description,
        TotalRows,
        AddCount,
        UpdateCount,
        DeleteCount,
        FilterInfo,
        RefDataID,
        ExtraData,
        UserID,
        Username,
        IPAddress,
        UserAgent,
        Url,
        SessionID,
        IsSuccess,
        ErrorMessage,
        CreatedUser
    )
    Values
    (
        @FormCode,
        @FormName,
        @ActionType,
        @ActionTitle,
        @Description,
        @TotalRows,
        @AddCount,
        @UpdateCount,
        @DeleteCount,
        @FilterInfo,
        @RefDataID,
        @ExtraData,
        @UserID,
        @Username,
        @IPAddress,
        @UserAgent,
        @Url,
        @SessionID,
        @IsSuccess,
        @ErrorMessage,
        @CreatedUser
    );

    Select Cast(Scope_Identity() As BigInt) As BookingLogID;
End
Go

If Object_Id('SYS_BookingLog_Get', 'P') Is Not Null
    Drop Procedure SYS_BookingLog_Get;
Go

Create Procedure SYS_BookingLog_Get
    @BookingLogID BigInt
As
Begin
    Set Nocount On;

    Select
        BookingLogID,
        FormCode,
        FormName,
        ActionType,
        ActionTitle,
        Description,
        TotalRows,
        AddCount,
        UpdateCount,
        DeleteCount,
        FilterInfo,
        RefDataID,
        ExtraData,
        UserID,
        Username,
        IPAddress,
        UserAgent,
        Url,
        SessionID,
        IsSuccess,
        ErrorMessage,
        CreatedDate,
        CreatedUser,
        UpdatedDate,
        UpdatedUser
    From SYS_BookingLog
    Where BookingLogID = @BookingLogID;
End
Go

If Object_Id('SYS_BookingLog_Update', 'P') Is Not Null
    Drop Procedure SYS_BookingLog_Update;
Go

Create Procedure SYS_BookingLog_Update
    @BookingLogID    BigInt,
    @FormCode        NVarChar(100) = Null,
    @FormName        NVarChar(250) = Null,
    @ActionType      NVarChar(50) = Null,
    @ActionTitle     NVarChar(500) = Null,
    @Description     NVarChar(2000) = Null,
    @TotalRows       Int = Null,
    @AddCount        Int = Null,
    @UpdateCount     Int = Null,
    @DeleteCount     Int = Null,
    @FilterInfo      NVarChar(1000) = Null,
    @RefDataID       BigInt = Null,
    @ExtraData       NVarChar(Max) = Null,
    @UserID          BigInt = Null,
    @Username        NVarChar(100) = Null,
    @IPAddress       NVarChar(50) = Null,
    @UserAgent       NVarChar(500) = Null,
    @Url             NVarChar(500) = Null,
    @SessionID       NVarChar(100) = Null,
    @IsSuccess       Bit = Null,
    @ErrorMessage    NVarChar(2000) = Null,
    @UpdatedUser     NVarChar(100) = Null
As
Begin
    Set Nocount On;

    Update SYS_BookingLog
    Set
        FormCode = IsNull(@FormCode, FormCode),
        FormName = IsNull(@FormName, FormName),
        ActionType = IsNull(@ActionType, ActionType),
        ActionTitle = IsNull(@ActionTitle, ActionTitle),
        Description = IsNull(@Description, Description),
        TotalRows = IsNull(@TotalRows, TotalRows),
        AddCount = IsNull(@AddCount, AddCount),
        UpdateCount = IsNull(@UpdateCount, UpdateCount),
        DeleteCount = IsNull(@DeleteCount, DeleteCount),
        FilterInfo = IsNull(@FilterInfo, FilterInfo),
        RefDataID = IsNull(@RefDataID, RefDataID),
        ExtraData = IsNull(@ExtraData, ExtraData),
        UserID = IsNull(@UserID, UserID),
        Username = IsNull(@Username, Username),
        IPAddress = IsNull(@IPAddress, IPAddress),
        UserAgent = IsNull(@UserAgent, UserAgent),
        Url = IsNull(@Url, Url),
        SessionID = IsNull(@SessionID, SessionID),
        IsSuccess = IsNull(@IsSuccess, IsSuccess),
        ErrorMessage = IsNull(@ErrorMessage, ErrorMessage),
        UpdatedDate = GetDate(),
        UpdatedUser = @UpdatedUser
    Where BookingLogID = @BookingLogID;

    Select @@RowCount As AffectedRows;
End
Go

If Object_Id('SYS_BookingLog_Delete', 'P') Is Not Null
    Drop Procedure SYS_BookingLog_Delete;
Go

Create Procedure SYS_BookingLog_Delete
    @BookingLogID BigInt
As
Begin
    Set Nocount On;

    Delete From SYS_BookingLog
    Where BookingLogID = @BookingLogID;

    Select @@RowCount As AffectedRows;
End
Go

If Object_Id('SYS_BookingLog_DeleteByDate', 'P') Is Not Null
    Drop Procedure SYS_BookingLog_DeleteByDate;
Go

Create Procedure SYS_BookingLog_DeleteByDate
    @BeforeDate DateTime
As
Begin
    Set Nocount On;

    Delete From SYS_BookingLog
    Where CreatedDate < @BeforeDate;

    Select @@RowCount As AffectedRows;
End
Go

If Object_Id('SYS_BookingLog_ViewPage', 'P') Is Not Null
    Drop Procedure SYS_BookingLog_ViewPage;
Go

Create Procedure SYS_BookingLog_ViewPage
    @Keyword     NVarChar(200) = Null,
    @FormCode    NVarChar(100) = Null,
    @ActionType  NVarChar(50) = Null,
    @Username    NVarChar(100) = Null,
    @FromDate    DateTime = Null,
    @ToDate      DateTime = Null,
    @PageIndex   Int = 1,
    @PageSize    Int = 20
As
Begin
    Set Nocount On;

    If @PageIndex Is Null Or @PageIndex < 1
        Set @PageIndex = 1;

    If @PageSize Is Null Or @PageSize < 1
        Set @PageSize = 20;

    ;With tblData As
    (
        Select
            BookingLogID,
            FormCode,
            FormName,
            ActionType,
            ActionTitle,
            Description,
            TotalRows,
            AddCount,
            UpdateCount,
            DeleteCount,
            FilterInfo,
            RefDataID,
            ExtraData,
            UserID,
            Username,
            IPAddress,
            UserAgent,
            Url,
            SessionID,
            IsSuccess,
            ErrorMessage,
            CreatedDate,
            CreatedUser,
            UpdatedDate,
            UpdatedUser,
            Count(1) Over() As TotalRowsCount,
            Row_Number() Over (Order By CreatedDate Desc, BookingLogID Desc) As RowNum
        From SYS_BookingLog
        Where
            (@Keyword Is Null Or @Keyword = ''
                Or FormCode Like '%' + @Keyword + '%'
                Or FormName Like '%' + @Keyword + '%'
                Or ActionTitle Like '%' + @Keyword + '%'
                Or Description Like '%' + @Keyword + '%'
                Or Username Like '%' + @Keyword + '%')
            And (@FormCode Is Null Or @FormCode = '' Or FormCode = @FormCode)
            And (@ActionType Is Null Or @ActionType = '' Or ActionType = @ActionType)
            And (@Username Is Null Or @Username = '' Or Username = @Username)
            And (@FromDate Is Null Or CreatedDate >= @FromDate)
            And (@ToDate Is Null Or CreatedDate < DateAdd(Day, 1, @ToDate))
    )
    Select
        BookingLogID,
        FormCode,
        FormName,
        ActionType,
        ActionTitle,
        Description,
        TotalRows,
        AddCount,
        UpdateCount,
        DeleteCount,
        FilterInfo,
        RefDataID,
        ExtraData,
        UserID,
        Username,
        IPAddress,
        UserAgent,
        Url,
        SessionID,
        IsSuccess,
        ErrorMessage,
        CreatedDate,
        CreatedUser,
        UpdatedDate,
        UpdatedUser,
        TotalRowsCount As TotalRows
    From tblData
    Where RowNum Between ((@PageIndex - 1) * @PageSize + 1) And (@PageIndex * @PageSize)
    Order By RowNum;
End
Go

