        (N'ExtraData',     N'Dữ liệu mở rộng dạng JSON/text, tùy từng form tự định nghĩa.'),
        (N'UserID',        N'Mã người dùng CMS thực hiện thao tác.'),
        (N'Username',      N'Tên đăng nhập người thực hiện thao tác.'),
        (N'IPAddress',     N'Địa chỉ IP của client thực hiện thao tác.'),
        (N'UserAgent',     N'Thông tin trình duyệt/client (User-Agent).'),
        (N'Url',           N'URL trang web nơi thực hiện thao tác.'),
        (N'SessionID',     N'Mã phiên làm việc (Session) của người dùng.'),
        (N'IsSuccess',     N'Trạng thái thao tác. 1: thành công, 0: thất bại.'),
