    Declare @colName SysName;
    Declare @colDesc NVarChar(500);
    Declare curDesc Cursor Local Fast_Forward For
        Select ColumnName, Description From @tblDesc;

    Open curDesc;
    Fetch Next From curDesc Into @colName, @colDesc;

    While @@Fetch_Status = 0
    Begin
        If Exists (
            Select 1
            From sys.columns
            Where object_id = Object_Id('SYS_BookingLog')
                And name = @colName
        )
        Begin
            If Not Exists (
                Select 1
                From sys.extended_properties ep
                Inner Join sys.columns c
                    On ep.major_id = c.object_id
                    And ep.minor_id = c.column_id
                Where ep.major_id = Object_Id('SYS_BookingLog')
                    And c.name = @colName
                    And ep.name = 'MS_Description'
            )
                Exec sys.sp_addextendedproperty
