                    @value = @colDesc,
                    @level0type = N'SCHEMA', @level0name = N'dbo',
                    @level1type = N'TABLE',  @level1name = N'SYS_BookingLog',
                    @level2type = N'COLUMN', @level2name = @colName;
        End

        Fetch Next From curDesc Into @colName, @colDesc;
    End

    Close curDesc;
    Deallocate curDesc;
End
