using System;
using System.Data;
using System.Web;
using System.Web.SessionState;
using CRMObject;

namespace InformationCMS.Helpers
{
    /// <summary>
    /// Helper ghi log thao tác Booking vào bảng SYS_BookingLog.
    /// Dùng chung cho nhiều form (tải HIS, sửa lịch, xuất excel...).
    /// </summary>
    public static class SYS_BookingLogHelper
    {
        public const string FORM_DOWNLOAD_BOOKING = "frmDownloadBooking";
        public const string FORM_NAME_DOWNLOAD_BOOKING = "Tải lịch hẹn từ HIS";

        public const string ACTION_DOWNLOAD = "DOWNLOAD";
        public const string ACTION_UPDATE = "UPDATE";
        public const string ACTION_INSERT = "INSERT";
        public const string ACTION_DELETE = "DELETE";
        public const string ACTION_EXPORT = "EXPORT";

        public static void TryWriteLog(
            HttpRequest request,
            HttpSessionState session,
            string formCode,
            string formName,
            string actionType,
            string actionTitle,
            string description,
            int? totalRows,
            int? addCount,
            int? updateCount,
            int? deleteCount,
            string filterInfo,
            string username,
            bool isSuccess,
            string errorMessage)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(formCode))
                    return;

                if (string.IsNullOrWhiteSpace(actionType))
                    return;

                var obj = new CRM_Booking();
                obj.GetDataTable(
                    "SYS_BookingLog_Add",
                    "@FormCode", formCode,
                    "@FormName", ToDbValue(formName),
                    "@ActionType", actionType,
                    "@ActionTitle", ToDbValue(actionTitle),
                    "@Description", ToDbValue(SafeGetStr(description, 2000)),
                    "@TotalRows", ToDbValue(totalRows),
                    "@AddCount", ToDbValue(addCount),
                    "@UpdateCount", ToDbValue(updateCount),
                    "@DeleteCount", ToDbValue(deleteCount),
                    "@FilterInfo", ToDbValue(SafeGetStr(filterInfo, 1000)),
                    "@RefDataID", DBNull.Value,
                    "@ExtraData", DBNull.Value,
                    "@UserID", DBNull.Value,
                    "@Username", ToDbValue(username),
                    "@IPAddress", ToDbValue(GetClientIPAddress(request)),
                    "@UserAgent", ToDbValue(SafeGetStr(request != null ? request.UserAgent : "", 500)),
                    "@Url", ToDbValue(SafeGetStr(request != null ? request.RawUrl : "", 500)),
                    "@SessionID", ToDbValue(session != null ? session.SessionID : ""),
                    "@IsSuccess", isSuccess,
                    "@ErrorMessage", ToDbValue(SafeGetStr(errorMessage, 2000)),
                    "@CreatedUser", ToDbValue(username)
                );
            }
            catch
            {
                // Không làm gián đoạn nghiệp vụ chính nếu ghi log lỗi
            }
        }

        private static object ToDbValue(string value)
        {
            if (string.IsNullOrWhiteSpace(value))
                return DBNull.Value;

            return value;
        }

        private static object ToDbValue(int? value)
        {
            if (!value.HasValue)
                return DBNull.Value;

            return value.Value;
        }

        private static string SafeGetStr(string value, int maxLength)
        {
            if (value == null)
                value = "";

            if (maxLength > 0 && value.Length > maxLength)
                value = value.Substring(0, maxLength);

            return value;
        }

        private static string GetClientIPAddress(HttpRequest request)
        {
            if (request == null)
                return "";

            try
            {
                string forwarded = request.Headers["X-Forwarded-For"];
                if (!string.IsNullOrEmpty(forwarded))
                {
                    string[] arr = forwarded.Split(',');
                    if (arr.Length > 0)
                        return arr[0].Trim();
                }

                string realIP = request.Headers["X-Real-IP"];
                if (!string.IsNullOrEmpty(realIP))
                    return realIP.Trim();

                if (!string.IsNullOrEmpty(request.UserHostAddress))
                    return request.UserHostAddress.Trim();
            }
            catch
            {
            }

            return "";
        }
    }
}

