/*
    Bảng log thao tác form Tải lịch hẹn từ HIS (rút gọn)
    -----------------------------------------------------------------------
    BookingLogID  : khóa chính
    ActionType    : DOWNLOAD | UPDATE
    Description   : mô tả chi tiết (ai làm gì, bộ lọc...)
    TotalRows     : tổng số dòng
    AddCount      : số dòng thêm mới (khi UPDATE)
    UpdateCount   : số dòng cập nhật (khi UPDATE)
    Username      : người thực hiện
    IsSuccess     : 1 thành công, 0 thất bại
    ErrorMessage  : lỗi (nếu có)
    CreatedDate   : ngày giờ ghi log
    -----------------------------------------------------------------------
    LƯU Ý: Nếu đã tạo bảng cũ (nhiều cột) và chưa cần giữ log:
        Drop Table SYS_BookingLog;
    Rồi chạy lại file này.
*/

If Not Exists (Select 1 From sys.tables Where name = 'SYS_BookingLog')
Begin
    Create Table SYS_BookingLog
    (
        BookingLogID    BigInt Identity(1,1) Not Null,
        ActionType      NVarChar(50) Not Null,
        Description     NVarChar(2000) Null,
        TotalRows       Int Null,
        AddCount        Int Null,
        UpdateCount     Int Null,
        Username        NVarChar(100) Null,
        IsSuccess       Bit Not Null Constraint DF_SYS_BookingLog_IsSuccess Default(1),
        ErrorMessage    NVarChar(500) Null,
        CreatedDate     DateTime Not Null Constraint DF_SYS_BookingLog_CreatedDate Default(GetDate()),
        Constraint PK_SYS_BookingLog Primary Key Clustered (BookingLogID)
    );

    Create NonClustered Index IX_SYS_BookingLog_CreatedDate
        On SYS_BookingLog (CreatedDate Desc);

    Create NonClustered Index IX_SYS_BookingLog_ActionType
        On SYS_BookingLog (ActionType, CreatedDate Desc);

    Create NonClustered Index IX_SYS_BookingLog_Username
        On SYS_BookingLog (Username, CreatedDate Desc);
End
Go

/*
    Mô tả bảng và từng cột (MS_Description)
*/
If Object_Id('SYS_BookingLog', 'U') Is Not Null
Begin
    If Not Exists (
        Select 1 From sys.extended_properties
        Where major_id = Object_Id('SYS_BookingLog') And minor_id = 0 And name = 'MS_Description'
    )
        Exec sys.sp_addextendedproperty
            @name = N'MS_Description',
            @value = N'Log thao tác form Tải lịch hẹn từ HIS',
            @level0type = N'SCHEMA', @level0name = N'dbo',
            @level1type = N'TABLE',  @level1name = N'SYS_BookingLog';
    Else
        Exec sys.sp_updateextendedproperty
            @name = N'MS_Description',
            @value = N'Log thao tác form Tải lịch hẹn từ HIS',
            @level0type = N'SCHEMA', @level0name = N'dbo',
            @level1type = N'TABLE',  @level1name = N'SYS_BookingLog';

    Declare @tblDesc Table (ColumnName SysName, Description NVarChar(500));
    Insert Into @tblDesc (ColumnName, Description) Values
        (N'BookingLogID',  N'Khóa chính. Mã log tự tăng.'),
        (N'ActionType',    N'Loại thao tác: DOWNLOAD (tải HIS), UPDATE (cập nhật CMS).'),
        (N'Description',   N'Mô tả chi tiết: ai thực hiện, làm gì, bộ lọc...'),
        (N'TotalRows',     N'Tổng số dòng dữ liệu.'),
        (N'AddCount',      N'Số dòng thêm mới (chỉ khi UPDATE).'),
        (N'UpdateCount',   N'Số dòng cập nhật (chỉ khi UPDATE).'),
        (N'Username',      N'Tên đăng nhập người thực hiện.'),
        (N'IsSuccess',     N'1: thành công, 0: thất bại.'),
        (N'ErrorMessage',  N'Thông báo lỗi khi thất bại.'),
        (N'CreatedDate',   N'Ngày giờ ghi log.');

    Declare @colName SysName;
    Declare @colDesc NVarChar(500);
    Declare curDesc Cursor Local Fast_Forward For
        Select ColumnName, Description From @tblDesc;

    Open curDesc;
    Fetch Next From curDesc Into @colName, @colDesc;

    While @@Fetch_Status = 0
    Begin
        If Exists (
            Select 1 From sys.columns
            Where object_id = Object_Id('SYS_BookingLog') And name = @colName
        )
        Begin
            If Not Exists (
                Select 1 From sys.extended_properties ep
                Inner Join sys.columns c On ep.major_id = c.object_id And ep.minor_id = c.column_id
                Where ep.major_id = Object_Id('SYS_BookingLog') And c.name = @colName And ep.name = 'MS_Description'
            )
                Exec sys.sp_addextendedproperty
                    @name = N'MS_Description', @value = @colDesc,
                    @level0type = N'SCHEMA', @level0name = N'dbo',
                    @level1type = N'TABLE',  @level1name = N'SYS_BookingLog',
                    @level2type = N'COLUMN', @level2name = @colName;
            Else
                Exec sys.sp_updateextendedproperty
                    @name = N'MS_Description', @value = @colDesc,
                    @level0type = N'SCHEMA', @level0name = N'dbo',
                    @level1type = N'TABLE',  @level1name = N'SYS_BookingLog',
                    @level2type = N'COLUMN', @level2name = @colName;
        End

        Fetch Next From curDesc Into @colName, @colDesc;
    End

    Close curDesc;
    Deallocate curDesc;
End
Go

If Object_Id('SYS_BookingLog_Add', 'P') Is Not Null
