Create Procedure SYS_BookingLog_Add
    @ActionType      NVarChar(50),
    @Description     NVarChar(2000) = Null,
    @TotalRows       Int = Null,
    @AddCount        Int = Null,
    @UpdateCount     Int = Null,
    @Username        NVarChar(100) = Null,
    @IsSuccess       Bit = 1,
    @ErrorMessage    NVarChar(500) = Null
As
Begin
    Set Nocount On;

    Insert Into SYS_BookingLog
    (
        ActionType,
        Description,
        TotalRows,
        AddCount,
        UpdateCount,
        Username,
        IsSuccess,
        ErrorMessage
    )
    Values
    (
        @ActionType,
        @Description,
        @TotalRows,
        @AddCount,
        @UpdateCount,
        @Username,
        @IsSuccess,
        @ErrorMessage
    );

    Select Cast(Scope_Identity() As BigInt) As BookingLogID;
End
