/*
    Mô tả bảng và từng cột (MS_Description)
*/
If Object_Id('SYS_BookingLog', 'U') Is Not Null
Begin
    If Not Exists (
        Select 1 From sys.extended_properties
        Where major_id = Object_Id('SYS_BookingLog') And minor_id = 0 And name = 'MS_Description'
    )
        Exec sys.sp_addextendedproperty
            @name = N'MS_Description',
            @value = N'Log thao tác Booking - dùng chung nhiều form/module',
            @level0type = N'SCHEMA', @level0name = N'dbo',
            @level1type = N'TABLE',  @level1name = N'SYS_BookingLog';
    Else
        Exec sys.sp_updateextendedproperty
            @name = N'MS_Description',
            @value = N'Log thao tác Booking - dùng chung nhiều form/module',
            @level0type = N'SCHEMA', @level0name = N'dbo',
            @level1type = N'TABLE',  @level1name = N'SYS_BookingLog';

    Declare @tblDesc Table (ColumnName SysName, Description NVarChar(500));
    Insert Into @tblDesc (ColumnName, Description) Values
        (N'BookingLogID',  N'Khóa chính. Mã log tự tăng.'),
        (N'FormCode',      N'Mã form/module. Vd: frmDownloadBooking.'),
        (N'FormName',      N'Tên hiển thị form. Vd: Tải lịch hẹn từ HIS.'),
        (N'ActionType',    N'Loại thao tác: DOWNLOAD, UPDATE, INSERT, DELETE, EXPORT.'),
        (N'ActionTitle',   N'Tiêu đề ngắn mô tả thao tác.'),
        (N'Description',   N'Mô tả chi tiết thao tác.'),
        (N'TotalRows',     N'Tổng số dòng dữ liệu liên quan.'),
        (N'AddCount',      N'Số dòng thêm mới.'),
        (N'UpdateCount',   N'Số dòng cập nhật.'),
        (N'DeleteCount',   N'Số dòng xóa.'),
        (N'FilterInfo',    N'Thông tin bộ lọc/điều kiện.'),
        (N'RefDataID',     N'Khóa tham chiếu dữ liệu nghiệp vụ.'),
        (N'ExtraData',     N'Dữ liệu mở rộng JSON/text.'),
        (N'UserID',        N'Mã người dùng CMS.'),
        (N'Username',      N'Tên đăng nhập người thực hiện.'),
        (N'IPAddress',     N'Địa chỉ IP client.'),
        (N'UserAgent',     N'Thông tin trình duyệt/client.'),
        (N'Url',           N'URL trang thực hiện thao tác.'),
        (N'SessionID',     N'Mã phiên làm việc.'),
        (N'IsSuccess',     N'1: thành công, 0: thất bại.'),
        (N'ErrorMessage',  N'Thông báo lỗi khi thất bại.'),
        (N'CreatedDate',   N'Ngày giờ ghi log.'),
        (N'CreatedUser',   N'Người tạo bản ghi log.'),
        (N'UpdatedDate',   N'Ngày giờ sửa log.'),
        (N'UpdatedUser',   N'Người sửa log.');

    Declare @colName SysName;
    Declare @colDesc NVarChar(500);
    Declare curDesc Cursor Local Fast_Forward For
        Select ColumnName, Description From @tblDesc;

    Open curDesc;
    Fetch Next From curDesc Into @colName, @colDesc;

    While @@Fetch_Status = 0
    Begin
        If Exists (
            Select 1 From sys.columns
            Where object_id = Object_Id('SYS_BookingLog') And name = @colName
        )
        Begin
            If Not Exists (
                Select 1 From sys.extended_properties ep
                Inner Join sys.columns c On ep.major_id = c.object_id And ep.minor_id = c.column_id
                Where ep.major_id = Object_Id('SYS_BookingLog') And c.name = @colName And ep.name = 'MS_Description'
            )
                Exec sys.sp_addextendedproperty
                    @name = N'MS_Description', @value = @colDesc,
                    @level0type = N'SCHEMA', @level0name = N'dbo',
                    @level1type = N'TABLE',  @level1name = N'SYS_BookingLog',
                    @level2type = N'COLUMN', @level2name = @colName;
            Else
                Exec sys.sp_updateextendedproperty
                    @name = N'MS_Description', @value = @colDesc,
                    @level0type = N'SCHEMA', @level0name = N'dbo',
                    @level1type = N'TABLE',  @level1name = N'SYS_BookingLog',
                    @level2type = N'COLUMN', @level2name = @colName;
        End

        Fetch Next From curDesc Into @colName, @colDesc;
    End

    Close curDesc;
    Deallocate curDesc;
End
