        @ActionTitle,
        @Description,
        @TotalRows,
        @AddCount,
        @UpdateCount,
        @DeleteCount,
        @FilterInfo,
        @RefDataID,
        @ExtraData,
        @UserID,
        @Username,
        @IPAddress,
        @UserAgent,
        @Url,
        @SessionID,
        @IsSuccess,
        @ErrorMessage,
        @CreatedUser
    );

    Select Cast(Scope_Identity() As BigInt) As BookingLogID;
End
